#!/usr/bin/env bash
# step54 — Footer: real brand-colored payment tiles (JazzCash, easypaisa, Bank,
# Raast, Binance, USDT) replacing the plain text chips.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step54-$TS
MD5="a8a45a7934b44096bc22576ed7a9c051"
mkdir -p "$BAK/views/partials"
cp "$APP/views/partials/store_bottom.ejs" "$BAK/views/partials/store_bottom.ejs"
restore(){ echo "!! rollback"; cp "$BAK/views/partials/store_bottom.ejs" "$APP/views/partials/store_bottom.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
echo "==> write store_bottom.ejs"
cat > /tmp/s54_sb.b64 <<'B64SB'

B64SB
base64 -d /tmp/s54_sb.b64 > "$APP/views/partials/store_bottom.ejs"; rm -f /tmp/s54_sb.b64
G=$(md5sum "$APP/views/partials/store_bottom.ejs"|awk '{print $1}'); echo "   md5 $G (expect $MD5)"
[ "$G" = "$MD5" ] || { echo "!! md5 mismatch"; false; }
echo "==> ejs compile"
node -e 'const ejs=require("/opt/gsz/node_modules/ejs"),fs=require("fs");ejs.compile(fs.readFileSync("/opt/gsz/views/partials/store_bottom.ejs","utf8"),{filename:"/opt/gsz/views/partials/store_bottom.ejs"});console.log("   OK");'
echo "==> pm2 restart"; pm2 restart gsz --update-env >/dev/null; sleep 3
H=$(curl -s -m 15 http://127.0.0.1:3900/ || true)
grep -q '</html>' <<<"$H" || { echo "!! home broken"; false; }
grep -q 'class="payl"' <<<"$H" || { echo "!! footer tiles missing"; false; }
grep -q 'JazzCash' <<<"$H" || { echo "!! JazzCash tile missing"; false; }
grep -q 'app.js?v=24' <<<"$H" || { echo "!! app.js version regressed"; false; }
trap - ERR
echo "==> step54 OK — footer payment logos live. Backup: $BAK"
